// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;
    function setUp() public { c = new Private_Bank(address(this)); }
    function testFuzz_property(uint256 amt, address actor) public {
        vm.assume(amt > 0 && amt <= c.MinDeposit());
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.Deposit{value: amt}();
        uint256 balBefore = c.balances(actor);
        vm.prank(actor);
        try c.CashOut(amt) { } catch { }
        assertEq(c.balances(actor), balBefore);
    }
}
